#include <vector>
#include <unordered_map>

class Solution {
public:
    long long countSpecialTriplets(std::vector<int>& nums) {
        int n = nums.size();
        if (n < 3) return 0;

        std::unordered_map<long long, int> right_counts, left_counts;
        for (int x : nums) right_counts[x]++;

        long long ans = 0;
        for (int x : nums) {
            right_counts[x]--;
            long long target = 2LL * x;
            ans += (long long)left_counts[target] * right_counts[target];
            left_counts[x]++;
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    public long countSpecialTriplets(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0;

        Map<Long, Integer> rightCounts = new HashMap<>();
        Map<Long, Integer> leftCounts = new HashMap<>();
        for (int x : nums) rightCounts.put((long) x, rightCounts.getOrDefault((long) x, 0) + 1);

        long ans = 0;
        for (int x : nums) {
            long lx = (long) x;
            rightCounts.put(lx, rightCounts.get(lx) - 1);
            long target = 2L * lx;
            int left = leftCounts.getOrDefault(target, 0);
            int right = rightCounts.getOrDefault(target, 0);
            ans += (long) left * right;
            leftCounts.put(lx, leftCounts.getOrDefault(lx, 0) + 1);
        }

        return ans;
    }
}

