var countSpecialTriplets = function(nums) {
    const n = nums.length;
    if (n < 3) return 0;

    const rightCounts = new Map();
    const leftCounts = new Map();
    for (const x of nums) {
        rightCounts.set(x, (rightCounts.get(x) || 0) + 1);
    }

    let ans = 0;
    for (const x of nums) {
        rightCounts.set(x, rightCounts.get(x) - 1);
        const target = 2 * x;
        const left = leftCounts.get(target) || 0;
        const right = rightCounts.get(target) || 0;
        ans += left * right;
        leftCounts.set(x, (leftCounts.get(x) || 0) + 1);
    }

    return ans;
};
